INSERT INTO math_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ( 'Mathematics Arithmetic Quiz', 'A quiz designed to test basic arithmetic skills including addition, subtraction, multiplication, and division.', '[{"id": "q1", "type": "fillInBlank", "question": "7,549 = 7,000 + ___ + 40 + 9", "hint": "Think about how to break down the number into thousands, hundreds, tens, and units.", "explanation": "The number 7,549 can be broken down into 7,000 + 500 + 40 + 9.", "correctAnswer": "500"}, {"id": "q2", "type": "fillInBlank", "question": "456 \u2212 385 = ___", "hint": "Subtract the smaller number from the larger number.", "explanation": "When you subtract 385 from 456, you get 71.", "correctAnswer": "71"}, {"id": "q3", "type": "fillInBlank", "question": "84 \u00f7 12 = ___", "hint": "Think about how many times 12 fits into 84.", "explanation": "12 goes into 84 exactly 7 times.", "correctAnswer": "7"}, {"id": "q4", "type": "fillInBlank", "question": "12 \u00d7 3 \u00d7 10 = ___", "hint": "Multiply the numbers step by step.", "explanation": "First, 12 \u00d7 3 = 36, then 36 \u00d7 10 = 360.", "correctAnswer": "360"}, {"id": "q5", "type": "fillInBlank", "question": "1,004,235 \u2212 52,346 = ___", "hint": "Perform the subtraction carefully, starting from the rightmost digit.", "explanation": "Subtracting 52,346 from 1,004,235 gives you 951,889.", "correctAnswer": "951889"}]', '8b9e97d4-2f6a-4794-b525-3c7f8a20730d', NOW());

INSERT INTO math_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ( 'Mathematics Reasoning Quiz', 'A quiz designed to test reasoning skills in mathematics for Key Stage 2 students, covering various topics including basic arithmetic, geometry, and number properties.', '[{"id": "q1", "type": "mcq", "question": "Which of the following angles is closest in size to a right angle?", "hint": "Think about the angle that forms a perfect corner.", "explanation": "A right angle is defined as an angle of exactly 90 degrees.", "correctAnswer": "b", "options": [{"id": "a", "text": "45 degrees"}, {"id": "b", "text": "90 degrees"}, {"id": "c", "text": "120 degrees"}, {"id": "d", "text": "180 degrees"}]}, {"id": "q2", "type": "fillInBlank", "question": "The sum of 5,350 and 1,000 is ___.", "hint": "Add the thousands place first.", "explanation": "When you add 1,000 to 5,350, you increase the thousands place by 1, resulting in 6,350.", "correctAnswer": "6350"}, {"id": "q3", "type": "mcq", "question": "How many groups of 3 can Ali make with 35 red counters?", "hint": "Divide the total number of counters by the group size.", "explanation": "35 divided by 3 equals 11 with a remainder, so the greatest number of complete groups is 11.", "correctAnswer": "b", "options": [{"id": "a", "text": "10"}, {"id": "b", "text": "11"}, {"id": "c", "text": "12"}, {"id": "d", "text": "13"}]}, {"id": "q4", "type": "multiSelect", "question": "Tick all the numbers that Olivia should say when counting in eights starting from zero.", "hint": "Look for multiples of 8.", "explanation": "The numbers 24, 78, and 112 are multiples of 8, while 42 is not.", "correctAnswer": ["a", "c", "d"], "options": [{"id": "a", "text": "24"}, {"id": "b", "text": "42"}, {"id": "c", "text": "78"}, {"id": "d", "text": "112"}]}, {"id": "q5", "type": "fillInBlank", "question": "The total distance from Paris to Munich is 860 kilometers. If the first two sections are 295 km and 331 km, the last section is ___ km.", "hint": "Subtract the sum of the first two sections from the total distance.", "explanation": "To find the last section, subtract 295 km and 331 km from 860 km, which equals 234 km.", "correctAnswer": "234"}]', '8b9e97d4-2f6a-4794-b525-3c7f8a20730d', NOW());

INSERT INTO math_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ( 'Mathematics Reasoning Quiz', 'A quiz designed to test reasoning skills in mathematics, covering various topics such as number properties, basic arithmetic, and geometry.', '[{"id": "q1", "type": "multiSelect", "question": "Tick all the numbers that are less than one million and fifty thousand.", "hint": "Consider the value of one million and fifty thousand.", "explanation": "1,049,900 and 1,030,900 are both less than 1,050,000.", "correctAnswer": ["b", "d"], "options": [{"id": "a", "text": "1,400,000"}, {"id": "b", "text": "1,049,900"}, {"id": "c", "text": "1,060,000"}, {"id": "d", "text": "1,030,900"}]}, {"id": "q2", "type": "mcq", "question": "Round the number 15,961 to the nearest hundred.", "hint": "Look at the tens digit to determine how to round.", "explanation": "The tens digit is 6, which means we round up to 16,000.", "correctAnswer": "b", "options": [{"id": "a", "text": "15,900"}, {"id": "b", "text": "16,000"}, {"id": "c", "text": "15,950"}, {"id": "d", "text": "15,800"}]}, {"id": "q3", "type": "fillInBlank", "question": "Jack buys 2 kilograms of pears for \u00a33.28. What is the cost of one kilogram of pears? \u00a3[blank]", "hint": "Divide the total cost by the number of kilograms.", "explanation": "To find the cost per kilogram, divide \u00a33.28 by 2, which equals \u00a31.64.", "correctAnswer": "1.64"}, {"id": "q4", "type": "mcq", "question": "What is the total mass of a truck that weighs 2,250 kilograms when loaded with 8 boxes, each weighing 25 kilograms?", "hint": "Calculate the total weight of the boxes and add it to the truck''s weight.", "explanation": "The total weight of the boxes is 8 * 25 = 200 kg. Adding this to the truck''s weight gives 2,250 + 200 = 2,450 kg.", "correctAnswer": "b", "options": [{"id": "a", "text": "2,500 kg"}, {"id": "b", "text": "2,750 kg"}, {"id": "c", "text": "3,000 kg"}, {"id": "d", "text": "2,800 kg"}]}, {"id": "q5", "type": "fillInBlank", "question": "Write all the possible two-digit numbers that are multiples of 7 and contain the digit 8: [blank]", "hint": "List the two-digit multiples of 7 and check for the digit 8.", "explanation": "The two-digit multiples of 7 that contain the digit 8 are 14, 21, 28, 35, 42, 49, 56, 63, 70, 77, 84, 91, and 98.", "correctAnswer": "14, 21, 28, 35, 42, 49, 56, 63, 70, 77, 84, 91, 98"}]', '8b9e97d4-2f6a-4794-b525-3c7f8a20730d', NOW());

INSERT INTO math_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ( 'Mathematics Arithmetic Quiz', 'A quiz designed to test basic arithmetic skills including addition, subtraction, multiplication, and division.', '[{"id": "q1", "type": "fillInBlank", "question": "689 + 38 = ___", "hint": "Think about how you can break down the addition into simpler parts.", "explanation": "To add 689 and 38, you can add 689 + 30 = 719 and then add 8 to get 727.", "correctAnswer": "727"}, {"id": "q2", "type": "fillInBlank", "question": "4,532 \u2212 19 = ___", "hint": "Subtract the smaller number from the larger number.", "explanation": "When you subtract 19 from 4,532, you get 4,513.", "correctAnswer": "4513"}, {"id": "q3", "type": "mcq", "question": "What is 6,600 \u00f7 6?", "hint": "Think about how many times 6 fits into 6,600.", "explanation": "6,600 divided by 6 equals 1,100 because 6 times 1,100 equals 6,600.", "correctAnswer": "a", "options": [{"id": "a", "text": "1,100"}, {"id": "b", "text": "1,200"}, {"id": "c", "text": "1,300"}, {"id": "d", "text": "1,400"}]}, {"id": "q4", "type": "fillInBlank", "question": "99 \u00d7 10 \u00d7 1 = ___", "hint": "Multiplying by 10 shifts the number one place to the left.", "explanation": "99 multiplied by 10 equals 990, and multiplying by 1 does not change the value.", "correctAnswer": "990"}, {"id": "q5", "type": "multiSelect", "question": "Which of the following are correct results of the operations? (Select all that apply)", "hint": "Calculate each operation carefully to find the correct answers.", "explanation": "Option a is correct because 15.5 divided by 100 equals 0.155. Option b is correct because 90 minus 56 equals 34. Option c is correct because 2,671 times 1,000 equals 2,671,000. Option d is incorrect because 43% of 900 equals 387, which is correct.", "correctAnswer": ["a", "b", "c"], "options": [{"id": "a", "text": "15.5 \u00f7 100 = 0.155"}, {"id": "b", "text": "90 \u2212 56 = 34"}, {"id": "c", "text": "2,671 \u00d7 1,000 = 2,671,000"}, {"id": "d", "text": "43% of 900 = 387"}]}]', '8b9e97d4-2f6a-4794-b525-3c7f8a20730d', NOW());

INSERT INTO math_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ( 'Key Stage 2 Mathematics Quiz', 'A quiz designed to test knowledge and reasoning skills in mathematics for Key Stage 2 students.', '[{"id": "q1", "type": "mcq", "question": "What is the total number of envelopes in a box that holds 40 packets, each containing 25 envelopes?", "hint": "Multiply the number of packets by the number of envelopes in each packet.", "explanation": "The total number of envelopes is calculated by multiplying 40 packets by 25 envelopes per packet, which equals 1000.", "correctAnswer": "a", "options": [{"id": "a", "text": "1000"}, {"id": "b", "text": "800"}, {"id": "c", "text": "600"}, {"id": "d", "text": "1200"}]}, {"id": "q2", "type": "fillInBlank", "question": "Olivia is thinking of a number that is greater than 236, less than 245, has a 3 in the tens'' place, and is an even number. What number is Olivia thinking of? ___", "hint": "Consider the range and the properties of the number.", "explanation": "The only even number between 236 and 245 with a 3 in the tens place is 240.", "correctAnswer": "240"}, {"id": "q3", "type": "multiSelect", "question": "Tick the two prime numbers that have a difference of 2: 15, 17, 19, 21, 23, 25.", "hint": "Look for pairs of numbers that are both prime and differ by 2.", "explanation": "The prime numbers 17 and 19 have a difference of 2.", "correctAnswer": ["b", "c"], "options": [{"id": "a", "text": "15"}, {"id": "b", "text": "17"}, {"id": "c", "text": "19"}, {"id": "d", "text": "21"}, {"id": "e", "text": "23"}, {"id": "f", "text": "25"}]}, {"id": "q4", "type": "mcq", "question": "If 3.207 is multiplied by 100, what is the result?", "hint": "Remember that multiplying by 100 shifts the decimal point two places to the right.", "explanation": "Multiplying 3.207 by 100 gives 3207.", "correctAnswer": "c", "options": [{"id": "a", "text": "320.7"}, {"id": "b", "text": "32.07"}, {"id": "c", "text": "3207"}, {"id": "d", "text": "3.207"}]}, {"id": "q5", "type": "fillInBlank", "question": "Mrs. Mills has 940 seeds and plants 12 seeds in each tray. What fraction of the last tray is filled? ___", "hint": "Calculate how many full trays can be filled and how many seeds are left.", "explanation": "940 divided by 12 gives 78 full trays with 4 seeds left, so the last tray is filled with 4 out of 12 seeds, which is 1/12.", "correctAnswer": "1/12"}]', '8b9e97d4-2f6a-4794-b525-3c7f8a20730d', NOW());

INSERT INTO math_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ( 'Mathematics Reasoning Quiz', 'A quiz designed to test reasoning skills in mathematics, covering various topics such as fractions, basic arithmetic, and problem-solving.', '[{"id": "q1", "type": "fillInBlank", "question": "The temperature in a freezer is \u201340 \u00b0C. The temperature increases by 10 \u00b0C. What is the new temperature? ___ \u00b0C", "hint": "Remember to add the increase to the initial temperature.", "explanation": "When you increase \u201340 \u00b0C by 10 \u00b0C, you move up the number line to \u201330 \u00b0C.", "correctAnswer": "\u201330"}, {"id": "q2", "type": "mcq", "question": "Jack buys milk for \u00a31.45 and orange juice for \u00a32.40. He pays with a \u00a35 note. How much change does Jack get?", "hint": "Calculate the total cost and subtract it from \u00a35.", "explanation": "The total cost is \u00a31.45 + \u00a32.40 = \u00a33.85. The change is \u00a35.00 - \u00a33.85 = \u00a31.15.", "correctAnswer": "b", "options": [{"id": "a", "text": "\u00a31.15"}, {"id": "b", "text": "\u00a31.55"}, {"id": "c", "text": "\u00a32.05"}, {"id": "d", "text": "\u00a32.55"}]}, {"id": "q3", "type": "multiSelect", "question": "Tick the numbers that are factors of both 54 and 72.", "hint": "A factor divides the number without leaving a remainder.", "explanation": "The common factors of 54 and 72 are 3, 6, and 9.", "correctAnswer": ["b", "d", "e"], "options": [{"id": "a", "text": "2"}, {"id": "b", "text": "3"}, {"id": "c", "text": "4"}, {"id": "d", "text": "6"}, {"id": "e", "text": "9"}]}, {"id": "q4", "type": "fillInBlank", "question": "Emma thinks of a number. She says, multiply by 2, add 11, divide by 3, and my answer is 9. What number did Emma think of? ___", "hint": "Work backwards from the answer to find the original number.", "explanation": "To find Emma''s number, reverse the operations: 9 * 3 = 27, 27 - 11 = 16, and 16 / 2 = 8.", "correctAnswer": "3"}, {"id": "q5", "type": "mcq", "question": "What is the diameter of the Moon to the nearest hundred kilometres if it is 3,476 kilometres?", "hint": "Round the number to the nearest hundred.", "explanation": "3,476 rounded to the nearest hundred is 3,500.", "correctAnswer": "b", "options": [{"id": "a", "text": "3,400 km"}, {"id": "b", "text": "3,500 km"}, {"id": "c", "text": "3,600 km"}, {"id": "d", "text": "3,700 km"}]}]', '8b9e97d4-2f6a-4794-b525-3c7f8a20730d', NOW());

